examples.template:
FlowRow(
    horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2),
    verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2),
    itemVerticalAlignment = Alignment.CenterVertically,
) {
    filters.forEach { (name, value) ->
        MonarchTag(
            text = "$name: $value",
            onRemove = { filters = filters.filterNot { it.first == name } },
            removeIcon = { MonarchIcon(SampleIcons.Close, null) },
            removeLabel = "Remove $name filter",
        )
    }
    if (filters.isNotEmpty()) {
        MonarchButton(
            text = "Clear all",
            onClick = { filters = emptyList() },
            variant = MonarchButtonVariant.Link,
            size = MonarchButtonSize.Sm,
        )
    }
}

examples.setupTemplate:
var filters by remember {
    mutableStateOf(
        listOf(
            {{filters.0.name}} to {{filters.0.value}},
            {{filters.1.name}} to {{filters.1.value}},
            {{filters.2.name}} to {{filters.2.value}},
        ),
    )
}

examples.setup:
